export function buildScorecardFromDictionary(
  dictionary: KpiDictionaryEntry[],
  actuals: Map<string, number>
): DeptScorecardEntry[] {
  return dictionary.map((kpi) => {
    const actual = actuals.get(kpi.kpiCode);
    const status = computeStatus(actual, kpi.target, kpi.direction);
    const scorePercent = computeScorePercent(actual, kpi.target, kpi.direction);
    return {
      ...kpi,
      actual,
      scorePercent,
      weightedScore: scorePercent !== undefined ? scorePercent * kpi.weight : undefined,
      status,
    };
  });
}

function computeStatus(
  actual: number | undefined,
  target: number | undefined,
  direction: "Higher is Better" | "Lower is Better"
): ScorecardStatus {
  if (actual === undefined || target === undefined) return "Pending";
  if (target === 0) return "On Track";
  const ratio = actual / target;
  if (direction === "Higher is Better") {
    if (ratio >= 1) return "Exceeded";
    if (ratio >= 0.9) return "On Track";
    if (ratio >= 0.7) return "At Risk";
    return "Missed";
  } else {
    if (ratio <= 1) return "Exceeded";
    if (ratio <= 1.1) return "On Track";
    if (ratio <= 1.3) return "At Risk";
    return "Missed";
  }
}

function computeScorePercent(
  actual: number | undefined,
  target: number | undefined,
  direction: "Higher is Better" | "Lower is Better"
): number | undefined {
  if (actual === undefined || target === undefined || target === 0) return undefined;
  if (direction === "Higher is Better") {
    return Math.min(Math.round((actual / target) * 100), 150);
  } else {
    return Math.min(Math.round((target / actual) * 100), 150);
  }
}

